package com.marketplace.application.party;
import com.marketplace.application.shared.NotFoundException; import com.marketplace.domain.party.*; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Transactional public class PartyApplicationService implements PartyUseCase { private final PartyRepository repo; public PartyApplicationService(PartyRepository repo){this.repo=repo;} public View create(PartyType t,Command c){return view(repo.save(Party.create(t,c.name(),c.email(),c.document())));} public View update(Long id,PartyType t,Command c){var p=find(id,t);p.update(c.name(),c.email(),c.document(),c.active());return view(repo.save(p));} @Transactional(readOnly=true) public View get(Long id,PartyType t){return view(find(id,t));} @Transactional(readOnly=true) public List<View> list(PartyType t){return repo.findActiveByType(t).stream().map(PartyApplicationService::view).toList();} public void deactivate(Long id,PartyType t){var p=find(id,t);p.update(p.name(),p.email(),p.document(),false);repo.save(p);} private Party find(Long id,PartyType t){return repo.findByIdAndType(id,t).orElseThrow(()->new NotFoundException(t==PartyType.CUSTOMER?"Cliente":"Vendedor",id));} private static View view(Party p){return new View(p.id(),p.type(),p.name(),p.email(),p.document(),p.active(),p.createdAt());} }
